  "التأكيد بيثبت أسعار كل الأصناف، وبيبعت أي أصناف لسه ما اتبعتتش للمطبخ كجولة جديدة. لو كله اتبعت، مفيش جولة جديدة.": "يثبّت التأكيد أسعار كل الأصناف، ويرسل للمطبخ ما لم يُرسل منها كجولة جديدة. إن أُرسل الكل فلا جولة جديدة.",
