  "الطباعة والإيصال الإلكتروني بيحصلوا بعد الحفظ؛ لو فشلوا البيع بيفضل خلصان (شوف طابور الطباعة والإيصال الإلكتروني).": "تتم الطباعة والإيصال الإلكتروني بعد الحفظ؛ إن فشلت يبقى البيع مكتملًا (راجع طابور الطباعة والإيصال الإلكتروني).",
