  "اختار شيك من شاشة الشيكات عشان تشوف إيصاله": "اختر شيكًا من شاشة الشيكات لعرض إيصاله",
  "الإيصال بيتبني من البيانات المحفوظة بس — مفيش أي حساب جديد. النسخة بيتكتب عليها \"نسخة\" ومش بتعمل إيصال جديد.": "يُبنى الإيصال من البيانات المحفوظة فقط — بلا أي حساب جديد. تُكتب على النسخة كلمة \"نسخة\" ولا تُنشئ إيصالًا جديدًا.",
