  "الإيصال الإلكتروني مش مفعّل (FiscalDocumentPolicy = OFF)": "الإيصال الإلكتروني غير مفعّل (FiscalDocumentPolicy = OFF)",
  "الخدمة مش على الإيصال الإلكتروني لحد قرار المحاسب (OD-EG-4)": "الخدمة غير مدرجة في الإيصال الإلكتروني حتى قرار المحاسب (OD-EG-4)",
  "ترتيب السطور: إجمالي الأصناف ← الخصم ← الخدمة ← ضريبة القيمة المضافة ← الإجمالي. الخدمة سطر لوحدها بين الإجمالي والضريبة.": "ترتيب السطور: إجمالي الأصناف ← الخصم ← الخدمة ← ضريبة القيمة المضافة ← الإجمالي. الخدمة سطر مستقل بين الإجمالي والضريبة.",
  "الشيك المبدئي \"ليست فاتورة ضريبية\": مفيهوش QR، وطباعته مش بتغير الشيك ومش محتاجة موافقة.": "الشيك المبدئي \"ليست فاتورة ضريبية\": بلا QR، وطباعته لا تغيّر الشيك ولا تحتاج موافقة.",
  "المرتجع فلوس بتطلع بموافقة مدير تاني. مش إرجاع فعلي للصنف ولا إشعار دائن ضريبي (قرار مفتوح H2).": "المرتجع مبلغ يُصرف بموافقة مدير آخر. ليس إرجاعًا فعليًا للصنف ولا إشعارًا دائنًا ضريبيًا (قرار مفتوح H2).",
