  "الموافقة REFUND_APPROVE دايمًا، ومن مدير غير اللي طلب (SelfApprovalPolicy). الصرف الكاش بيطلع من درج مفتوح على الجهاز ده ويتحسب في يوم الصرف.": "الموافقة REFUND_APPROVE دائمًا، ومن مدير غير الطالب (SelfApprovalPolicy). يُصرف النقد من درج نقدية مفتوح على هذا الجهاز ويُحتسب في يوم الصرف.",
