  "اتجاه مقترح: Reservation.* موقوفة لقرار (PD_HELD)، والعربون عملية مقترحة. العربون التزام مش مبيعات لحد ما يتخصم من شيك.": "اتجاه مقترح: Reservation.* موقوفة لقرار (PD_HELD)، والعربون عملية مقترحة. العربون التزام وليس مبيعات حتى يُخصم من شيك.",
