  "العربون بيدخل الدرج لو كاش، بس محاسبيًا التزام. بيتحول مبيعات لما يتخصم من شيك (من شاشة التحصيل)، أو يتصادر لو العميل ما جاش (سؤال للمحاسب: إيراد ولا لأ؟).": "يدخل العربون النقدي درج النقدية، لكنه محاسبيًا التزام. يتحول إلى مبيعات عند خصمه من شيك (من شاشة التحصيل)، أو يُصادر إن لم يحضر العميل (سؤال للمحاسب: إيراد أم لا؟).",
