  "اقفل": "إغلاق",
  "إقفال أعمى: اعد الدرج واكتب المبلغ من غير ما تشوف المتوقع (BlindClosePolicy). الفرق بيطلع من السيرفر بعد القفل.": "إغلاق أعمى: عُدّ الدرج وأدخل المبلغ دون رؤية المتوقع (BlindClosePolicy). يظهر الفرق من الخادم بعد الإغلاق.",
  "الإقفال الأعمى مقفول: المتوقع": "الإغلاق الأعمى معطل: المتوقع",
  "الكاش المعدود في الدرج": "النقد المعدود في الدرج",
  "ملاحظة (لو في فرق)": "ملاحظة (عند وجود فرق)",
  "الفرق فوق حد SESSION_VARIANCE بيطلب موافقة مدير. شيكات الصالة المأكدة والمش مدفوعة مش بتمنع القفل — بتظهر في Z كشيكات مفتوحة. طلبات التيك أواي المفتوحة على الوردية دي بتمنع (SESSION_HAS_OPEN_ORDERS).": "الفرق فوق حد SESSION_VARIANCE يتطلب موافقة مدير. شيكات الصالة المؤكدة غير المدفوعة لا تمنع الإغلاق — تظهر في Z كشيكات مفتوحة. طلبات التيك أواي المفتوحة على هذه الوردية تمنعه (SESSION_HAS_OPEN_ORDERS).",
  "البقشيش اتوزع": "تم توزيع البقشيش",
  "وزّع": "توزيع",
  "البقشيش فلوس لوحدها مش مبيعات. TipPolicy لازم تكون ON (من لوحة الإعدادات) عشان يظهر في الدفع. التوزيع حسب TipDistributionPolicy (لكل ويتر أو صندوق مشترك).": "البقشيش نقدية مستقلة وليس مبيعات. يجب أن تكون TipPolicy = ON (من لوحة الإعدادات) ليظهر في الدفع. التوزيع حسب TipDistributionPolicy (لكل ويتر أو صندوق مشترك).",
  "كل موافقة مدير بتتستخدم مرة واحدة، ومربوطة بالعملية والسياق والطالب والفرع والجهاز، وليها وقت انتهاء. السجل بيقول مين عمل إيه، وبأي أمر، وبأي موافقة.": "كل موافقة مدير تُستخدم مرة واحدة، وترتبط بالعملية والسياق والطالب والفرع والجهاز، ولها وقت انتهاء. يبيّن السجل من فعل ماذا، وبأي أمر، وبأي موافقة.",
  "على إيه": "على ماذا",
