  "بيظهر آخر {n} عملية.": "تظهر آخر {n} عملية.",
  "كل شيك بيخلص بيطلع له إيصال إلكتروني من البيانات المتجمدة وقت الإقفال. الإرسال للمنصة بيحصل بعد البيع — عمره ما بيوقف بيع.": "كل شيك ينتهي يصدر له إيصال إلكتروني من البيانات المجمّدة لحظة الإغلاق. يتم الإرسال للمنصة بعد البيع — ولا يوقف البيع أبدًا.",
  "افحص السلسلة": "فحص السلسلة",
  "مقفول — مفيش إيصالات بتتعمل": "معطل — لا تُصدر إيصالات",
