  "بيتغير من لوحة السياسات، وممكن يختلف لكل فرع. الإنتاج بس بعد ملف ضريبي وأجهزة نشطة.": "يتغير من لوحة السياسات، وقد يختلف لكل فرع. الإنتاج فقط بعد ملف ضريبي وأجهزة نشطة.",
