  "عدّى 20 ساعة": "مضت 20 ساعة",
  "أي إيصال ما اتقبلش بيطلع تنبيه عند 12 ساعة (تحذير) و20 ساعة (خطر) قبل آخر ميعاد 24 ساعة. جرّب تقدّم الساعة من أدوات العرض.": "أي إيصال لم يُقبل يُنبَّه عنه عند 12 ساعة (تحذير) و20 ساعة (خطر) قبل الموعد النهائي 24 ساعة. جرّب تقديم الساعة من أدوات العرض.",
  "الخدمة بتفضل برة الإيصال الإلكتروني لحد ما المحاسب يحدد هي T9 ولا T17 (OD-EG-4). عشان كده المشكلة SERVICE_CHARGE_UNMAPPED معلومة بس — مش بتوقف بناء الإيصال.": "تبقى الخدمة خارج الإيصال الإلكتروني حتى يحدد المحاسب هل هي T9 أم T17 (OD-EG-4). لذلك المشكلة SERVICE_CHARGE_UNMAPPED للعلم فقط — لا توقف بناء الإيصال.",
  "فيه {n} إيصال قرب على آخر ميعاد (24 ساعة) — صلّح البيانات أو اعمل إعادة إصدار.": "يوجد {n} إيصال اقترب من الموعد النهائي (24 ساعة) — صحّح البيانات أو أعد الإصدار.",
