  "لسه فيه بيانات ناقصة — الإيصال فاضل \"مستني بيانات\"": "ما زالت هناك بيانات ناقصة — بقي الإيصال \"بانتظار البيانات\"",
  "الإيصال اتبنى واتربط بالسلسلة — هيتبعت للمنصة أوتوماتيك": "تم بناء الإيصال وربطه بالسلسلة — سيُرسل للمنصة تلقائيًا",
  "اتعمل إيصال مصحح بيشاور على الإيصال المرفوض (referenceOldUUID)": "تم إنشاء إيصال مصحح يشير إلى الإيصال المرفوض (referenceOldUUID)",
  "الإيصال هيتبني تاني من نفس البيانات المتجمدة بعد ما صلّحت البيانات الناقصة (مثلًا أكواد الأصناف من شاشة التسجيل الضريبي). لو لسه فيه حاجة ناقصة هيفضل \"مستني بيانات\".": "سيُعاد بناء الإيصال من البيانات المجمّدة نفسها بعد تصحيح البيانات الناقصة (مثل رموز الأصناف من شاشة التسجيل الضريبي). إن بقي نقص يظل \"بانتظار البيانات\".",
  "الإيصال المرفوض هيبقى \"اتستبدل\"، وهيتعمل إيصال جديد بيشاور عليه (referenceOldUUID). الشيك نفسه مش بيتغير.": "يصبح الإيصال المرفوض \"مستبدلًا\"، ويُنشأ إيصال جديد يشير إليه (referenceOldUUID). لا يتغير الشيك نفسه.",
  "تجهيز الإيصال الإلكتروني (منظومة الإيصال الإلكتروني — مصلحة الضرائب): ملف الفرع، جهاز ضريبي لكل كاشير، وكود لكل صنف. أي بيانات ناقصة بتخلّي الإيصال \"مستني بيانات\" — والبيع بيكمل عادي.": "تجهيز الإيصال الإلكتروني (منظومة الإيصال الإلكتروني — مصلحة الضرائب): ملف الفرع، وجهاز ضريبي لكل كاشير، ورمز لكل صنف. أي نقص في البيانات يجعل الإيصال \"بانتظار البيانات\" — ويستمر البيع عاديًا.",
  "— العقود فيها أوامر كتابة بس ومفيش قراءة للملف والأجهزة والأكواد، فالقراءة دي مقترحة.": "— العقود بها أوامر كتابة فقط ولا قراءة للملف والأجهزة والرموز، لذا هذه القراءة مقترحة.",
