  "طول ما الجهاز موقوف، إيصالات الكاشير ده هتبقى \"مستني بيانات\" لحد ما يرجع نشط أو يتسجل جهاز تاني. البيع مش بيقف.": "ما دام الجهاز موقوفًا، تبقى إيصالات هذا الكاشير \"بانتظار البيانات\" حتى يعود نشطًا أو يُسجَّل جهاز آخر. البيع لا يتوقف.",
