  "كل سطر على الإيصال لازم يبقى له كود صنف مسجل ونوع وحدة. أي صنف من غير كود بيخلّي إيصاله \"مستني بيانات\" (ITEM_CODE_MISSING) لحد ما تضيف الكود وتعمل إعادة بناء. الأكواد بتتخزن في محوّل الإيصال المصري بس، مش في المنيو.": "كل سطر في الإيصال يحتاج رمز صنف مسجلًا ونوع وحدة. الصنف بلا رمز يجعل إيصاله \"بانتظار البيانات\" (ITEM_CODE_MISSING) حتى تضيف الرمز وتعيد البناء. تُخزَّن الرموز في محوّل الإيصال المصري فقط، لا في قائمة الطعام.",
