  "أول خطوات التجهيز (J-A1 من 2 لـ 4): بيانات النشاط، الفروع بالتقويم بتاعها، والأجهزة. كل جهاز جديد بيظهر فوق كشريحة جهاز تقدر تشتغل عليه.": "أولى خطوات التجهيز (J-A1 من 2 إلى 4): بيانات النشاط، والفروع بتقويمها، والأجهزة. يظهر كل جهاز جديد في الأعلى كشريحة جهاز يمكن العمل عليها.",
