  "اليوم التجاري بيتحسب على السيرفر لكل فرع من المنطقة الزمنية وساعة بداية اليوم، عمره ما بيتاخد من ساعة الجهاز. أي عملية قبل ساعة البداية بتتحسب على اليوم اللي فات: بيعة الساعة 2 الفجر بتدخل في تقارير امبارح.": "يُحسب اليوم التجاري في الخادم لكل فرع من المنطقة الزمنية وساعة بداية اليوم، ولا يؤخذ من ساعة الجهاز أبدًا. أي عملية قبل ساعة البداية تُحتسب على اليوم السابق: بيع الساعة 2 فجرًا يدخل في تقارير الأمس.",
