  "Terminal.Register في العقد فيه الكود والاسم والفرع بس. النوع والدرج إضافة مقترحة عشان النموذج يعرف شكل الجهاز (PROTOTYPE_GAPS).": "Terminal.Register في العقد يتضمن الرمز والاسم والفرع فقط. النوع والدرج إضافة مقترحة ليعرف النموذج شكل الجهاز (PROTOTYPE_GAPS).",
