  "طبّق بروفايل مصر": "تطبيق ملف مصر",
  "فريق التركيب بيطبق ملف السوق المصري مرة واحدة على نشاط فاضي (من غير HTTP ومن غير موافقة)، وبعدها يراجع كل قيمة مع صاحب المطعم. بعد كده أي تغيير بيعدي من شاشة الإعدادات بموافقة.": "يطبّق فريق التركيب ملف السوق المصري مرة واحدة على نشاط فارغ (بلا HTTP وبلا موافقة)، ثم يراجع كل قيمة مع صاحب المطعم. بعدها يمر أي تغيير عبر شاشة الإعدادات بموافقة.",
  "البروفايل متطبق بالفعل. في النظام الحقيقي التطبيق التاني بيترفض بـ SETTINGS_PROFILE_ALREADY_APPLIED.": "الملف مُطبَّق بالفعل. في النظام الفعلي يُرفض التطبيق الثاني بـ SETTINGS_PROFILE_ALREADY_APPLIED.",
