  "تعديلات المنيو والأسعار والضرايب بتسري على التسعيرات الجديدة بس؛ السطور المسجلة في الشيكات بتفضل بسعرها.": "تسري تعديلات القائمة والأسعار والضرائب على التسعيرات الجديدة فقط؛ تحتفظ السطور المسجلة في الشيكات بسعرها.",
  "السعر الساري دلوقتي": "السعر الساري الآن",
  "مفيش سعر — الصنف مش هيتباع هنا (PRICE_NOT_FOUND)": "لا يوجد سعر — لن يُباع الصنف هنا (PRICE_NOT_FOUND)",
