  "مفيش أسعار للفرع والقناة دي": "لا توجد أسعار لهذا الفرع وهذه القناة",
  "الفترة اللي بدأت عمر سعرها ما بيتغير — بتتقفل بس وتبدأ فترة جديدة. ده السجل الكامل للأسعار اللي اتطبقت.": "لا يتغير سعر فترة بدأت أبدًا — تُغلق فقط وتبدأ فترة جديدة. هذا السجل الكامل للأسعار المطبقة.",
  "السعر اتحفظ": "تم حفظ السعر",
  "لحد 4 خانات عشرية — العملة من الفرع (EGP)": "حتى 4 خانات عشرية — العملة من الفرع (ج.م)",
  "يبدأ إمتى": "موعد البدء",
