  "السياسة IMMEDIATE_ONLY — الجدولة هتترفض (PRICE_SCHEDULING_NOT_ALLOWED)": "السياسة IMMEDIATE_ONLY — ستُرفض الجدولة (PRICE_SCHEDULING_NOT_ALLOWED)",
  "ممنوع تاريخ فات (مفيش أثر رجعي)": "لا يُسمح بتاريخ سابق (لا أثر رجعي)",
  "ليه نهاية": "له نهاية",
  "بعد النهاية الصنف هيفضل من غير سعر في الفرع والقناة دي (PRICE_NOT_FOUND) لحد ما تحط سعر جديد. السعر المؤقت اللي يرجع لوحده مكانه العروض.": "بعد النهاية يبقى الصنف بلا سعر في هذا الفرع وهذه القناة (PRICE_NOT_FOUND) حتى تضع سعرًا جديدًا. السعر المؤقت الذي يعود تلقائيًا مكانه العروض.",
  "لو السياسة بتطلب موافقة على تغيير السعر، شاشة موافقة المدير هتظهر لوحدها.": "إن كانت السياسة تتطلب موافقة على تغيير السعر، تظهر شاشة موافقة المدير تلقائيًا.",
  "الفترة القديمة اتقفلت": "أُغلقت الفترة القديمة",
  "الأرقام من سجل الأسعار على السيرفر (الفترة السارية). دوس على صنف عشان تعدل سعره.": "الأرقام من سجل الأسعار في الخادم (الفترة السارية). اضغط على صنف لتعديل سعره.",
  "فيه سعر مجدول": "يوجد سعر مجدول",
  "رجعت للطابور — نفس المهمة ونفس النسخة، مش نسخة جديدة": "أُعيدت إلى الطابور — المهمة والنسخة نفسها، لا نسخة جديدة",
  "كل ورقة بتطلع من النظام مهمة في الطابور. الطباعة بتحصل بعد ما البيع يتسجل — فشل الطابعة عمره ما بيوقف بيع.": "كل ورقة تخرج من النظام مهمة في الطابور. تتم الطباعة بعد تسجيل البيع — ولا يوقف فشل الطابعة البيع أبدًا.",
  "إعادة كل الواقفة": "إعادة كل المتوقفة",
  "{n} مهمة طباعة وقفت بعد 5 محاولات — محتاجة \"إعادة\"": "{n} مهمة طباعة توقفت بعد 5 محاولات — تحتاج \"إعادة\"",
  "{n} مهمة فشلت وهتتعاد أوتوماتيك": "{n} مهمة فشلت وستُعاد تلقائيًا",
  "البيع اتسجل خلاص ومش هيتلغي. صلّح الطابعة (ورق / كهربا / شبكة) وبعدين اعمل إعادة.": "سُجّل البيع ولن يُلغى. أصلح الطابعة (الورق / الكهرباء / الشبكة) ثم نفّذ الإعادة.",
  "محتاجة تدخل (فشلت أو وقفت)": "تحتاج تدخلًا (فشلت أو توقفت)",
  "المحاولة الجاية": "المحاولة التالية",
  "مفيش مهام طباعة — بيع حاجة على الكاشير وهتظهر هنا": "لا توجد مهام طباعة — بِع صنفًا على الكاشير لتظهر هنا",
  "دلوقتي": "الآن",
  "خلصت المحاولات": "انتهت المحاولات",
  "نفس المهمة ونفس النسخة": "المهمة والنسخة نفسها",
  "إزاي الطباعة شغالة": "كيف تعمل الطباعة",
  "البيع بيتسجل الأول، وبعدين الطباعة بتتعمل كمهمة لوحدها. لو الطابعة واقعة الكاشير يكمل بيع عادي.": "يُسجَّل البيع أولًا، ثم تُنفَّذ الطباعة كمهمة مستقلة. إن تعطلت الطابعة يواصل الكاشير البيع عاديًا.",
  "المحاولات أوتوماتيك: بعد 5 ث، 15 ث، 45 ث، 2 د، 5 د. بعد 5 محاولات فاشلة المهمة \"بتقف\" وتظهر هنا بالأحمر.": "المحاولات تلقائية: بعد 5 ث، 15 ث، 45 ث، 2 د، 5 د. بعد 5 محاولات فاشلة \"تتوقف\" المهمة وتظهر هنا بالأحمر.",
  "\"إعادة\" بترجع نفس المهمة ونفس النسخة للطابور — عمرها ما بتطلع نسخة زيادة. لو المهمة اتبعتت أو لسه مستنية بيرفض (PRINT_JOB_NOT_RETRYABLE).": "\"إعادة\" تعيد المهمة والنسخة نفسها إلى الطابور — ولا تُخرج نسخة زائدة أبدًا. إن كانت المهمة أُرسلت أو ما زالت منتظرة تُرفض (PRINT_JOB_NOT_RETRYABLE).",
  "\"اطبع نسخة\" بتعمل مهمة جديدة مكتوب عليها \"نسخة\" ومش بتطلع إيصال جديد. موافقة المدير عليها حسب السياسة (RECEIPT_REPRINT) — اقتراح docs/30: أول نسخة مجانية وبعدها موافقة.": "\"طباعة نسخة\" تنشئ مهمة جديدة مكتوبًا عليها \"نسخة\" ولا تُصدر إيصالًا جديدًا. موافقة المدير عليها حسب السياسة (RECEIPT_REPRINT) — اقتراح docs/30: أول نسخة مجانية ثم بموافقة.",
  "\"اتبعت للطابعة\" معناها إن الطابعة استلمت البيانات — الطابعات الحرارية مش بتأكد إن الورقة طلعت فعلًا، فإحنا مش بنقول \"اتطبع\".": "\"أُرسل للطابعة\" يعني أن الطابعة استلمت البيانات — الطابعات الحرارية لا تؤكد خروج الورقة فعلًا، لذا لا نقول \"تمت الطباعة\".",
  "جرّب: من \"المحاكاة\" فوق خلّي طابعة الكاشير \"واقعة\" أو \"الورق خلص\"، وبيع حاجة.": "جرّب: من \"المحاكاة\" في الأعلى اجعل طابعة الكاشير \"معطلة\" أو \"نفد الورق\"، ثم بِع صنفًا.",
