  "دور تاني": "دور آخر",
  "اتعمل المستخدم {n}": "تم إنشاء المستخدم {n}",
  "فريد؛ تكراره بيرجع USERNAME_TAKEN": "فريد؛ تكراره يعيد USERNAME_TAKEN",
  "الاسم اللي بيظهر": "الاسم المعروض",
  "الباسورد": "كلمة المرور",
  "على الأقل {n} حروف (CredentialPolicy)": "{n} أحرف على الأقل (CredentialPolicy)",
  "قصير — السيرفر هيرفض CREDENTIAL_POLICY_VIOLATION": "قصيرة — سيرفض الخادم CREDENTIAL_POLICY_VIOLATION",
  "{n} أرقام بالظبط (CredentialPolicy)": "{n} أرقام بالضبط (CredentialPolicy)",
  "لازم {n} أرقام": "يلزم {n} أرقام",
  "في التركيب الحقيقي الرقم السري والباسورد بيوصلوا للشخص نفسه (Credential.Reset)، عمرهم ما بيتكتبوا في محضر. من غير PIN المستخدم لازم يغيّر بياناته أول ما يدخل.": "في التركيب الفعلي يصل الرقم السري وكلمة المرور إلى الشخص نفسه (Credential.Reset)، ولا يُكتبان في محضر أبدًا. بلا PIN يجب على المستخدم تغيير بياناته عند أول دخول.",
  "اتحدثت صلاحيات {n}": "تم تحديث صلاحيات {n}",
  "الحساب شغال": "الحساب مفعّل",
  "الإيقاف بيلغي كل جلسات المستخدم: الجهاز اللي داخل بيه هيرجع لشاشة الدخول مع أول عملية (N8).": "الإيقاف يلغي كل جلسات المستخدم: يعود الجهاز المسجّل به لشاشة الدخول مع أول عملية (N8).",
  "لو مفيش حد تاني يقدر يدير الصلاحيات، السيرفر بيرفض LAST_OWNER_PROTECTED. النسخة {v} (expectedVersion).": "إن لم يوجد شخص آخر يدير الصلاحيات يرفض الخادم LAST_OWNER_PROTECTED. النسخة {v} (expectedVersion).",
