  "إعادة التعيين بتفك القفل لو الحساب مقفول من محاولات غلط، وبتخلّي المستخدم يغيّر الرقم أول ما يدخل.": "إعادة التعيين تفك قفل الحساب المقفل بسبب محاولات خاطئة، وتُلزم المستخدم بتغيير الرقم عند أول دخول.",
  "الصلاحيات اللي عليها \"أضيفت للنموذج\" مش في أدوار ملف التجهيز 1.2 — النموذج زوّدها عشان الخبير يقدر يجرب كل الشاشات (PROTOTYPE_GAPS).": "الصلاحيات الموسومة \"أُضيفت للنموذج\" ليست في أدوار ملف التجهيز 1.2 — أضافها النموذج ليجرب الخبير كل الشاشات (PROTOTYPE_GAPS).",
