  "الأحجام والكومبو والنص ونص اتجاه للمنتج — مش في العقود المبنية لسه. السعر بيطلع من السيرفر في التسعيرة بس.": "المقاسات والكومبو ونصف ونصف اتجاه للمنتج — ليست في العقود المبنية بعد. يأتي السعر من الخادم في التسعيرة فقط.",
