  "الصنف اتبعت للمطبخ، فمينفعش يتشال. الإلغاء محتاج موافقة مدير حسب السياسة (LINE_VOID)، وبيظهر مشطوب على شاشة المطبخ.": "أُرسل الصنف للمطبخ فلا يمكن إزالته. الإلغاء يحتاج موافقة مدير حسب السياسة (LINE_VOID)، ويظهر مشطوبًا على شاشة المطبخ.",
