  "الخصم بيقلل الأصناف والخدمة بالتناسب. PricingOrderPolicy بيحدد قبل الضريبة ولا بعدها. التجميع ممنوع افتراضيًا (DiscountStackingPolicy).": "يخفّض الخصم الأصناف والخدمة بالتناسب. يحدد PricingOrderPolicy هل يكون قبل الضريبة أم بعدها. التجميع ممنوع افتراضيًا (DiscountStackingPolicy).",
