  "قاعدة واحدة ثابتة: القروش بتتوزع بأكبر باقي والفرق الأخير على آخر حصة (SplitAllocationPolicy). خصم النسبة بيتنسخ لكل حصة، وخصم المبلغ بيتوزع بنفس القاعدة، والخدمة بتتحسب لكل شيك.": "قاعدة واحدة ثابتة: تُوزَّع القروش بأكبر باقٍ ويذهب الفرق الأخير لآخر حصة (SplitAllocationPolicy). يُنسخ خصم النسبة لكل حصة، ويُوزَّع خصم المبلغ بالقاعدة نفسها، وتُحتسب الخدمة لكل شيك.",
  "Order.Split موقوفة لقرار (PD_HELD) في العقد — ده اتجاه مقترح. التقسيم بالأصناف موجود فعلًا عن طريق \"نقل أصناف\".": "Order.Split موقوفة لقرار (PD_HELD) في العقد — هذا اتجاه مقترح. التقسيم بالأصناف متاح فعلًا عبر \"نقل أصناف\".",
