  "مطعم فاضي: ادخل من «الإدارة» باسم كريم (مهندس التركيب)، أو امشي مع رحلة «تركيب مطعم من الصفر»": "مطعم فارغ: ادخل من «الإدارة» باسم كريم (مهندس التركيب)، أو اتبع رحلة «تركيب مطعم من الصفر»",
