  "بنجرّب حاجات المفروض السيستم يرفضها أو يتصرف فيها صح: ضغطتين ورا بعض، جهازين في نفس اللحظة، رد بيضيع، حد بيحاول يوافق لنفسه…": "نجرّب ما يجب أن يرفضه النظام أو يتعامل معه بشكل صحيح: ضغطتان متتاليتان، جهازان في اللحظة نفسها، رد يضيع، شخص يحاول الموافقة لنفسه…",
  "خلصت كل التجارب": "انتهت كل التجارب",
  "كل تجربة بتتأكد إن النتيجة زي المتوقع وإن مفيش حاجة زيادة اتسجلت. بتشتغل على بيانات التجربة الحالية.": "تتحقق كل تجربة من أن النتيجة كما هو متوقع ومن عدم تسجيل أي شيء زائد. تعمل على بيانات التجربة الحالية.",
