  "{n} موقف ممكن يحصل في مطعم، متقسمين على {g} مجال. اختار المواقف اللي عاوز تشوفها في العرض واضغط «عاوز أشوف ده» — بتتحفظ في الملاحظات.": "{n} موقف قد يحدث في مطعم، موزعة على {g} مجال. اختر المواقف التي تريد رؤيتها في العرض واضغط «أريد رؤية هذا» — تُحفظ في الملاحظات.",
