  "محاكاة الأعطال: وقّع الطابعة أو شاشة المطبخ أو منظومة الضرايب أو النت، وشوف إن البيع بيكمل": "محاكاة الأعطال: عطّل الطابعة أو شاشة المطبخ أو منظومة الضرائب أو الإنترنت، وتحقق من استمرار البيع",
  "في عطل شغال": "يوجد عطل نشط",
  "مفيش شبكة حقيقية ولا دفع حقيقي ولا منظومة ضرايب حقيقية. الطباعة والمطبخ والإيصال الإلكتروني بيحصلوا بعد ما البيع يتحفظ، ووقوعهم عمره ما يوقف البيع.": "لا شبكة فعلية ولا دفع فعلي ولا منظومة ضرائب فعلية. تتم الطباعة والمطبخ والإيصال الإلكتروني بعد حفظ البيع، ولا يوقف تعطلها البيع أبدًا.",
  "رجّع كله شغال": "إعادة تشغيل الكل",
  "النت على كل جهاز": "الاتصال على كل جهاز",
  "اقطع النت عن جهاز: البيع بيكمل عليه والحركات بتستنى لحد ما النت يرجع.": "اقطع الاتصال عن جهاز: يستمر البيع عليه وتنتظر الحركات عودة الاتصال.",
  "توصيل الطلبات لشاشة المطبخ": "إرسال الطلبات لشاشة المطبخ",
  "منظومة الإيصال الإلكتروني (الضرايب)": "منظومة الإيصال الإلكتروني (الضرائب)",
  "البرامج التانية المربوطة (الحسابات، تطبيقات الدليفري)": "البرامج الأخرى المرتبطة (الحسابات، تطبيقات التوصيل)",
  "لو واقعة، التحديثات اللي بتتبعت لها بتستنى وتتعاد أوتوماتيك — تقدر تتابعها من «صحة النظام».": "إن تعطلت، تنتظر التحديثات المرسلة إليها وتُعاد تلقائيًا — تابعها من «صحة النظام».",
