  "الحركة الجاية من النوع ده هتتنفذ بس ردها هيضيع — هتشوف «النتيجة مش معروفة» وزرار «إعادة المحاولة».": "ستُنفَّذ الحركة التالية من هذا النوع لكن يضيع ردها — سترى «النتيجة غير معروفة» وزر «إعادة المحاولة».",
  "الحركة الجاية تفشل قبل ما توصل (مفيش حاجة هتتسجل)": "فشل الحركة التالية قبل وصولها (لن يُسجَّل شيء)",
  "في عطل شغال دلوقتي": "يوجد عطل نشط الآن",
  "كل رحلة قصة من يوم في المطعم: مين بيعمل إيه وعلى أنهي جهاز، والمفروض تشوف إيه. اعمل الخطوة بإيدك على الجهاز، أو خلّي السيستم يعملها قدامك.": "كل رحلة قصة من يوم في المطعم: من يفعل ماذا وعلى أي جهاز، وما الذي يجب أن تراه. نفّذ الخطوة يدويًا على الجهاز، أو دع النظام ينفذها أمامك.",
  "بتبدأ بمطعم فاضي خالص (بيانات التجربة بتتمسح، وتقدر ترجعها بعدين)": "تبدأ بمطعم فارغ تمامًا (تُحذف بيانات التجربة ويمكن استعادتها لاحقًا)",
