  "«ورّيني على الجهاز» بيجهّز الجهاز وإنت تعمل الخطوة بنفسك. «خلّي السيستم يعملها» بيعملها لوحده وتشوف النتيجة على الأجهزة.": "«العرض على الجهاز» يجهّز الجهاز لتنفذ الخطوة بنفسك. «تنفيذ تلقائي» ينفذها النظام وترى النتيجة على الأجهزة.",
