  "مثلًا: دفعت 20 جنيه مواصلات للطيار": "مثال: دُفع 20 ج.م مواصلات للطيار",
  "لو فيه فرق في العد لازم مدير يوافق. شيكات الصالة اللي لسه ما اتدفعتش مش بتمنع القفل وبتظهر في التقرير. طلبات التيك أواي المفتوحة على الدرج ده لازم تتحصّل أو تتنقل لدرج تاني الأول.": "فرق العد يحتاج موافقة مدير. شيكات الصالة غير المدفوعة لا تمنع الإغلاق وتظهر في التقرير. طلبات التيك أواي المفتوحة على هذا الدرج يجب تحصيلها أو نقلها لدرج آخر أولًا.",
  "البقشيش فلوس لوحدها مش مبيعات. بيتوزع حسب الإعدادات: كل ويتر بتاعه، أو صندوق مشترك بيتقسم على الكل.": "البقشيش نقدية مستقلة وليس مبيعات. يُوزَّع حسب الإعدادات: لكل ويتر بقشيشه، أو صندوق مشترك يُقسَّم على الجميع.",
