  "كل موافقة مدير بتتستخدم مرة واحدة على حركة واحدة بعينها. والسجل بيقول مين عمل إيه، إمتى، ومن أنهي جهاز.": "كل موافقة مدير تُستخدم مرة واحدة على حركة محددة. ويبيّن السجل من فعل ماذا، ومتى، ومن أي جهاز.",
