  "اعرض أكتر": "عرض المزيد",
  "كل شيك بيتقفل بيطلع له إيصال إلكتروني لمصلحة الضرايب. الإرسال بيحصل بعد البيع — عمره ما بيوقف بيع.": "كل شيك يُغلق يصدر له إيصال إلكتروني لمصلحة الضرائب. يتم الإرسال بعد البيع — ولا يوقف البيع أبدًا.",
  "افحص تسلسل الإيصالات": "فحص تسلسل الإيصالات",
  "مش متاح للحساب ده": "غير متاح لهذا الحساب",
  "مفيش إيصالات بتتعمل": "لا تُصدر إيصالات",
  "بيتبعت لبيئة التجربة بس": "يُرسل لبيئة التجربة فقط",
  "إيصالات حقيقية للمصلحة": "إيصالات فعلية للمصلحة",
