  "قربت من مهلة الـ 24 ساعة": "اقتربت من مهلة الـ 24 ساعة",
  "الخدمة بتفضل برة الإيصال الإلكتروني لحد ما المحاسب يحدد نوع الضريبة بتاعها — ودي ملاحظة بس، مش بتوقف الإيصال.": "تبقى الخدمة خارج الإيصال الإلكتروني حتى يحدد المحاسب نوع ضريبتها — وهذه ملاحظة فقط لا توقف الإيصال.",
  "كل إيصال مربوط باللي قبله على نفس الجهاز — لو فيه إيصال ناقص أو متغير السلسلة بتتكسر.": "كل إيصال مرتبط بسابقه على الجهاز نفسه — إن نقص إيصال أو تغيّر انكسرت السلسلة.",
  "الفحص الكامل على السيرفر لسه مش متاح للحساب ده — ده فحص سريع من الإيصالات اللي في الطابور.": "الفحص الكامل في الخادم غير متاح لهذا الحساب بعد — هذا فحص سريع من الإيصالات في الطابور.",
  "كل الإيصالات ماشية تمام. لو صنف ناقصه كود، الإيصال بتاعه هيظهر هنا.": "كل الإيصالات سليمة. إن نقص رمز صنف يظهر إيصاله هنا.",
  "اقفل شيك على الكاشير وإيصاله هيظهر هنا.": "أغلق شيكًا على الكاشير ليظهر إيصاله هنا.",
  "المنظومة رفضت الإيصال — صلّح البيانات واعمل إيصال مصحح.": "رفضت المنظومة الإيصال — صحّح البيانات وأصدر إيصالًا مصححًا.",
  "لسه ما اتعملش — مستني البيانات": "لم يُنشأ بعد — بانتظار البيانات",
  "لسه فيه بيانات ناقصة — الإيصال فاضل مستني": "ما زالت هناك بيانات ناقصة — الإيصال ما زال منتظرًا",
  "اتعمل إيصال مصحح بيشاور على الإيصال المرفوض": "تم إنشاء إيصال مصحح يشير إلى الإيصال المرفوض",
  "الإيصال هيتبني تاني من نفس بيانات الشيك بعد ما صلّحت الناقص (مثلًا أكواد الأصناف من شاشة التسجيل الضريبي). لو لسه فيه حاجة ناقصة هيفضل مستني.": "سيُعاد بناء الإيصال من بيانات الشيك نفسه بعد تصحيح الناقص (مثل رموز الأصناف من شاشة التسجيل الضريبي). إن بقي نقص يظل منتظرًا.",
  "الإيصال المرفوض هيتعلم «اتستبدل»، وهيتعمل إيصال جديد بيشاور عليه. الشيك نفسه مش بيتغير.": "يُعلَّم الإيصال المرفوض «مستبدل»، ويُنشأ إيصال جديد يشير إليه. لا يتغير الشيك نفسه.",
  "تجهيز الإيصال الإلكتروني مع مصلحة الضرايب: بيانات الفرع، جهاز ضريبي لكل كاشير، وكود لكل صنف. أي بيانات ناقصة بتخلّي الإيصال يستنى — والبيع بيكمل عادي.": "تجهيز الإيصال الإلكتروني مع مصلحة الضرائب: بيانات الفرع، وجهاز ضريبي لكل كاشير، ورمز لكل صنف. أي نقص في البيانات يجعل الإيصال ينتظر — ويستمر البيع عاديًا.",
