  "السعر اللي بدأ ما بيتغيرش — بيتقفل وتبدأ فترة جديدة. ده السجل الكامل للأسعار اللي اتطبقت.": "السعر الذي بدأ لا يتغير — يُغلق وتبدأ فترة جديدة. هذا السجل الكامل للأسعار المطبقة.",
