  "كل ورقة بتطلع من السيستم بتستنى هنا لحد ما الطابعة تستلمها. البيع بيتسجل الأول — عطل الطابعة عمره ما بيوقف بيع.": "كل ورقة تخرج من النظام تنتظر هنا حتى تستلمها الطابعة. يُسجَّل البيع أولًا — ولا يوقف عطل الطابعة البيع أبدًا.",
