  "خمس حاجات تعرفها عن الطابعة والطابور.": "خمسة أمور عن الطابعة والطابور.",
  "«إعادة» بترجّع نفس الورقة للطابور — عمرها ما بتطلع نسخة زيادة. الورقة اللي اتبعتت أو لسه مستنية مينفعش تتعاد.": "«إعادة» تعيد الورقة نفسها للطابور — ولا تُخرج نسخة زائدة أبدًا. لا تُعاد ورقة أُرسلت أو ما زالت منتظرة.",
  "«اطبع نسخة» بتطبع ورقة جديدة مكتوب عليها «نسخة»، مش إيصال جديد. ممكن تحتاج موافقة مدير حسب الإعدادات (أول نسخة من غير موافقة وبعدها موافقة).": "«طباعة نسخة» تطبع ورقة جديدة مكتوبًا عليها «نسخة»، لا إيصالًا جديدًا. قد تحتاج موافقة مدير حسب الإعدادات (أول نسخة بلا موافقة ثم بموافقة).",
  "العرض اتعدل — الشيكات اللي عليها العرض بتفضل بالنسخة القديمة": "تم تعديل العرض — تحتفظ الشيكات التي عليها العرض بالنسخة القديمة",
  "هابي أور، خصم على أصناف معينة، اشتري وخد، وأكواد خصم — بمواعيد وحدود استخدام. السيستم هو اللي بيحسب الخصم على الشيك.": "هابي أور، وخصم على أصناف محددة، واشترِ واحصل، ورموز خصم — بمواعيد وحدود استخدام. يحسب النظام الخصم على الشيك.",
  "شغالة دلوقتي": "مفعّلة الآن",
  "الشيك عليه خصم واحد بس: يا عرض يا خصم مدير.": "خصم واحد فقط على الشيك: إما عرض أو خصم مدير.",
  "ينفع أكتر من خصم على نفس الشيك — بس العرض اللي متعلم \"لوحده\" مش بيتجمع مع حاجة.": "يمكن تطبيق أكثر من خصم على الشيك نفسه — إلا العرض المعلَّم \"منفرد\" فلا يُجمع مع غيره.",
