  "الفرع اللي مالوش قيمة خاصة بياخد قيمة المطعم كله. التغيير بيطبق على اللي جاي بس — الشيكات القديمة محتفظة بقيمتها. الموافقة لازم تيجي من مدير غير اللي طلب التغيير (مثلًا هبة — مديرة الفرع).": "الفرع الذي لا قيمة خاصة له يأخذ قيمة المطعم كله. يُطبَّق التغيير على ما يأتي فقط — تحتفظ الشيكات السابقة بقيمتها. يجب أن تأتي الموافقة من مدير غير طالب التغيير (مثل هبة — مديرة الفرع).",
  "جرّب كلمة تانية زي: خدمة، درج، خصم، ضريبة.": "جرّب كلمة أخرى مثل: خدمة، درج، خصم، ضريبة.",
