  "لو التغيير محتاج موافقة، هتظهر شاشة «موافقة مدير». نفس الشخص مينفعش يوافق على طلبه — اختار مدير تاني (مثلًا هبة — مديرة الفرع). الموافقة بتبقى على التغيير ده بالظبط.": "إن كان التغيير يحتاج موافقة تظهر شاشة «موافقة مدير». لا يوافق الشخص نفسه على طلبه — اختر مديرًا آخر (مثل هبة — مديرة الفرع). تكون الموافقة على هذا التغيير بالضبط.",
