  "لكل نوع حركة: «من قايمة ثابتة» يعني الموظف يختار سبب من القايمة دي بس، و«كتابة حرة» يعني يكتب السبب بإيده (بتتغير من تبويب «إعدادات المطعم»). القايمة لازم يفضل فيها سبب واحد شغال على الأقل.": "لكل نوع حركة: «من قائمة ثابتة» أي يختار الموظف سببًا من هذه القائمة فقط، و«كتابة حرة» أي يكتب السبب بنفسه (يتغير من تبويب «إعدادات المطعم»). يجب أن يبقى في القائمة سبب مفعّل واحد على الأقل.",
