  "الجهاز ده مش متربط بفرع، والمحطات والترابيزات تبع فرع. ادخل من جهاز في الفرع أو اختار الفرع من شاشة الدخول.": "هذا الجهاز غير مرتبط بفرع، والمحطات والترابيزات تتبع فرعًا. ادخل من جهاز في الفرع أو اختر الفرع من شاشة الدخول.",
