  "مفيش محطة افتراضية مخفية: لازم قاعدة «أي حاجة تانية» في الآخر عشان أي صنف جديد يوصل لمحطة.": "لا محطة افتراضية مخفية: يلزم قاعدة «أي شيء آخر» في النهاية ليصل أي صنف جديد إلى محطة.",
