  "مجموعات الضريبة (النسبة، شاملة ولا بتتضاف، التقريب، المعفي)، والأصناف اللي على كل مجموعة، وطريقة عرض الأسعار على الكاشير. النسب بيانات صاحب المطعم والمحاسب.": "مجموعات الضريبة (النسبة، شاملة أم مضافة، التقريب، المعفاة)، والأصناف على كل مجموعة، وطريقة عرض الأسعار على الكاشير. النسب من بيانات صاحب المطعم والمحاسب.",
  "مجموعة الضريبة اتعملت — مش هتغير أي سعر لحد ما صنف يتربط بيها": "تم إنشاء مجموعة الضريبة — لن تغيّر أي سعر حتى يُربط بها صنف",
  "اتعدلت — بتسري على الطلبات الجديدة بس": "تم التعديل — يسري على الطلبات الجديدة فقط",
  "رجعت": "تمت الاستعادة",
  "اتأرشفت": "تمت الأرشفة",
  "تغيير النسبة أو طريقة الحساب أو التقريب بيطلب موافقة حسب الإعدادات، وبيسري على الطلبات الجديدة بس. المجموعة اللي عليها أصناف ما تتأرشفش، ومفيش مسح.": "تغيير النسبة أو طريقة الحساب أو التقريب يتطلب موافقة حسب الإعدادات، ويسري على الطلبات الجديدة فقط. لا تُؤرشف مجموعة عليها أصناف، ولا حذف.",
