  "الأسعار شاملة الضريبة: الشيك بيطلّع الضريبة من جوه السعر ومش بيزودها. الإيصال بيكتب \"شاملة في الأسعار\".": "الأسعار شاملة الضريبة: يستخرج الشيك الضريبة من داخل السعر ولا يضيفها. يكتب الإيصال \"شاملة في الأسعار\".",
  "تغيير الاسم بس مش محتاج موافقة. أي تغيير في النسبة أو الحساب أو التقريب أو الأكواد بيطلب موافقة حسب الإعدادات.": "تغيير الاسم وحده لا يحتاج موافقة. أي تغيير في النسبة أو الحساب أو التقريب أو الرموز يتطلب موافقة حسب الإعدادات.",
