  "كل صنف بيتغير لوحده (ولو الإعدادات بتطلب موافقة على تغيير ضريبة صنف، هتظهر الموافقة). الشيكات القديمة بتفضل بضريبتها.": "يتغير كل صنف منفردًا (وإن كانت الإعدادات تتطلب موافقة على تغيير ضريبة صنف تظهر الموافقة). تحتفظ الشيكات السابقة بضريبتها.",
