  "ده عرض بس: الرقم بيتحسب على السيرفر (المتصفح ما بيحسبش). الشيك والإيصال بيفضلوا يحسبوا الضريبة بنفس الطريقة. الأصناف اللي ضريبتها شاملة أصلًا أو معفية بتظهر زي ما هي.": "هذا عرض فقط: يُحسب الرقم في الخادم (لا يحسب المتصفح). يواصل الشيك والإيصال حساب الضريبة بالطريقة نفسها. الأصناف الشاملة للضريبة أصلًا أو المعفاة تظهر كما هي.",
