  "في التشغيل الحقيقي الرقم السري بيوصل للموظف نفسه وما بيتكتبش في أي ورق. من غير PIN الموظف هيغيّر بياناته أول ما يدخل.": "في التشغيل الفعلي يصل الرقم السري إلى الموظف نفسه ولا يُكتب على أي ورق. بلا PIN يغيّر الموظف بياناته عند أول دخول.",
