  "الوجبة اتحفظت": "تم حفظ الوجبة",
  "الصنف رجع صنف عادي (مش وجبة)": "عاد الصنف صنفًا عاديًا (ليس وجبة)",
  "الوجبة صنف ليه سعر واحد، ومكوّنة من اختيارات (ساندوتش، بطاطس، مشروب…). كل اختيار فيه أصناف، واحد منهم الافتراضي، والباقي ممكن بفرق ترقية. سعر الوجبة بيتوزع على المكونات بنسبة أسعارهم عشان كل مكوّن ياخد ضريبته، وكل مكوّن بيروح محطة المطبخ بتاعته.": "الوجبة صنف بسعر واحد يتكون من اختيارات (ساندويتش، بطاطس، مشروب…). لكل اختيار أصناف، أحدها الافتراضي، والباقي بفرق ترقية. يُوزَّع سعر الوجبة على المكونات بنسبة أسعارها ليأخذ كل مكوّن ضريبته، ويذهب كل مكوّن إلى محطته في المطبخ.",
  "الصنف ده مفعّل عليه نص ونص — الوجبة ماينفعش تبقى نص ونص. اقفل نص ونص الأول.": "هذا الصنف مفعّل عليه نصف ونصف — لا تكون الوجبة نصفًا ونصفًا. عطّل نصف ونصف أولًا.",
