  "الإضافات على الصنف (بالترتيب اللي هيظهر للكاشير)": "الإضافات على الصنف (بترتيب ظهورها للكاشير)",
  "المجموعات نفسها (الاختيارات والأسعار والإجباري) بتتعدل من تبويب \"الإضافات\" في المنيو.": "تُعدَّل المجموعات نفسها (الاختيارات والأسعار والإلزامي) من تبويب \"الإضافات\" في قائمة الطعام.",
