  "السطور المسجلة في الشيكات بتفضل بضريبتها. لو الصنف جزء من وجبة، الجزء بتاعه في الوجبة بياخد الضريبة دي.": "تحتفظ السطور المسجلة في الشيكات بضريبتها. إن كان الصنف جزءًا من وجبة يأخذ جزؤه فيها هذه الضريبة.",
