  "الصنف مش في أي منيو شغال — مش هيظهر على الكاشير. ضيفه لمنيو من تبويب \"المنيوهات والمواعيد\".": "الصنف ليس في أي قائمة مفعّلة — لن يظهر على الكاشير. أضفه لقائمة من تبويب \"قوائم الطعام والمواعيد\".",
