  "لو نفس الشخص متسجل مرتين (برقم تاني مثلاً)، ادمج التاني هنا: العناوين والطلبات والنقاط بتتنقل للعميل ده، ورقمه بيبقى الرقم التاني، والعميل التاني بيتقفل.": "إن سُجّل الشخص نفسه مرتين (برقم آخر مثلًا)، ادمج الثاني هنا: تُنقل العناوين والطلبات والنقاط إلى هذا العميل، ويصبح رقمه الرقم الثاني، ويُغلق العميل الآخر.",
