  "وقفت بعد محاولات كتير. صلّح السبب (مثلاً شغّل الطابعة أو جدّد مفتاح الربط) وبعدين \"ابعت تاني\" — محتاجة موافقة مدير.": "توقفت بعد محاولات كثيرة. أصلح السبب (مثل تشغيل الطابعة أو تجديد مفتاح الربط) ثم \"إعادة الإرسال\" — تحتاج موافقة مدير.",
