  "الكاشير الجديد يبقى المسؤول عن الشيك": "يصبح الكاشير الجديد مسؤولًا عن الشيك",
  "مثلاً: تسليم وردية": "مثال: تسليم وردية",
  "الشيك بيتنقل بكل اللي عليه (الأصناف والدفعات اللي اتعملت). الكاشير الجديد هو اللي هيحصّل الباقي، والنقل بيتسجل في تاريخ الشيك. بعد كده الوردية القديمة تقدر تقفل.": "يُنقل الشيك بكل ما عليه (الأصناف والدفعات المنفذة). يحصّل الكاشير الجديد الباقي، ويُسجَّل النقل في سجل الشيك. بعدها يمكن إغلاق الوردية القديمة.",
