  "الأصناف بتروح المطبخ لوحدها أول ما الشيك يتأكد.": "تُرسل الأصناف للمطبخ تلقائيًا فور تأكيد الشيك.",
  "الشيك كله بيبقى مجاني (المطلوب صفر)، والسبب بيتسجل في تقرير الاستثناءات.": "يصبح الشيك كله مجانيًا (المطلوب صفر)، ويُسجَّل السبب في تقرير الاستثناءات.",
  "ده محتاج موافقة مدير دايمًا. الشيك اللي عليه فلوس اتدفعت مينفعش يتلغي — اعمل له مرتجع.": "يحتاج هذا موافقة مدير دائمًا. لا يُلغى شيك عليه مدفوعات — أنشئ له مرتجعًا.",
  "اتبعت تاني — من غير ما الطلب يتكرر": "أُعيد الإرسال — دون تكرار الطلب",
  "شيل الصنف": "إزالة الصنف",
  "اتعمل واترمى (هالك)": "حُضّر وأُتلف (هالك)",
