  "مفيش أسباب متسجلة للنوع ده — المدير يضيفها من الإعدادات.": "لا توجد أسباب مسجلة لهذا النوع — يضيفها المدير من الإعدادات.",
  "الصنف اتبعت للمطبخ فمينفعش يتشال. الإلغاء ممكن يحتاج موافقة مدير، وبيظهر مشطوب على شاشة المطبخ.": "أُرسل الصنف للمطبخ فلا يمكن إزالته. قد يحتاج الإلغاء موافقة مدير، ويظهر مشطوبًا على شاشة المطبخ.",
  "الملاحظة وصلت للمطبخ": "وصلت الملاحظة للمطبخ",
  "ابعت الملاحظة": "إرسال الملاحظة",
  "الملاحظة بتظهر على نفس الطلب في المطبخ تحت الصنف، من غير ما السعر يتغير.": "تظهر الملاحظة على الطلب نفسه في المطبخ تحت الصنف، دون تغيير السعر.",
  "طبّق الخصم": "تطبيق الخصم",
  "مثلًا WELCOME50": "مثال: WELCOME50",
  "الخصم بيتوزع على الأصناف والخدمة بالتناسب. خصمين على نفس الشيك مش مسموح.": "يُوزَّع الخصم على الأصناف والخدمة بالتناسب. لا يُسمح بخصمين على الشيك نفسه.",
  "مش بيتطبق لوحده، اختاره من «كود عرض».": "لا يُطبَّق وحده، اختره من «رمز عرض».",
  "الأصناف اتنقلت": "تم نقل الأصناف",
  "الأصناف اللي اتبعتت بتتنقل زي ما هي (مش بتتبعت للمطبخ تاني)، والشيكين بيتحدثوا مع بعض.": "تُنقل الأصناف المرسلة كما هي (لا تُرسل للمطبخ مجددًا)، ويُحدَّث الشيكان معًا.",
  "على كام واحد؟": "على كم شخصًا؟",
  "لازم كل صنف يكون متعيّن لكرسي (زرار الكرسي على كل سطر).": "يجب تعيين كل صنف لمقعد (زر المقعد في كل سطر).",
  "القروش بتتوزع بحيث مجموع الشيكات يساوي الأصل بالظبط. خصم النسبة بيتطبق على كل شيك، وخصم المبلغ بيتوزع، والخدمة بتتحسب لكل شيك.": "تُوزَّع القروش بحيث يساوي مجموع الشيكات الأصل تمامًا. يُطبَّق خصم النسبة على كل شيك، ويُوزَّع خصم المبلغ، وتُحتسب الخدمة لكل شيك.",
  "التقسيم ده اتجاه مقترح لسه مستني قرار. التقسيم بالأصناف موجود فعلًا من «نقل أصناف».": "هذا التقسيم اتجاه مقترح بانتظار قرار. التقسيم بالأصناف متاح فعلًا من «نقل أصناف».",
  "الشيك اللي هيتدمج في الشيك ده": "الشيك الذي سيُدمج في هذا الشيك",
  "حوّل الطلب لصالة": "تحويل الطلب إلى صالة",
  "حوّل الطلب لتيك أواي": "تحويل الطلب إلى تيك أواي",
  "نوع الطلب اتغير": "تم تغيير نوع الطلب",
  "الأصناف وأسعارها واللي اتبعت للمطبخ بيفضلوا زي ما هم. الخدمة بتتحسب حسب النوع الجديد.": "تبقى الأصناف وأسعارها وما أُرسل للمطبخ كما هي. تُحتسب الخدمة حسب النوع الجديد.",
  "مفيش حاجة مالية بتتعدل أو تتمسح: أي تصحيح بيتسجل كحركة جديدة مربوطة بالأصل.": "لا يُعدَّل أو يُحذف أي شيء مالي: يُسجَّل أي تصحيح كحركة جديدة مرتبطة بالأصل.",
