  "قفل الشيك": "إغلاق الشيك",
  "افتح ترابيزة، خد الطلب، وابعته للمطبخ على دفعات.": "افتح ترابيزة، وسجّل الطلب، وأرسله للمطبخ على دفعات.",
  "افتح الوردية، بيع تيك أواي، حصّل شيكات الترابيزات، واقفل الدرج.": "افتح الوردية، وبِع تيك أواي، وحصّل شيكات الترابيزات، وأغلق الدرج.",
  "شوف الطلبات اللي بتوصل لكل محطة، ابدأها وخلّصها.": "تابع الطلبات الواصلة لكل محطة، وابدأها وأنهِها.",
  "وافق على الإلغاءات والمرتجعات، تابع الشيكات والتقارير.": "وافق على الإلغاءات والمرتجعات، وتابع الشيكات والتقارير.",
  "المنيو والأسعار والإعدادات والتقارير — وكل الصلاحيات.": "قائمة الطعام والأسعار والإعدادات والتقارير — وكل الصلاحيات.",
  "ابدأ بمطعم فاضي: الفرع والأجهزة والناس والمنيو لحد أول بيعة.": "ابدأ بمطعم فارغ: الفرع والأجهزة والموظفين وقائمة الطعام حتى أول بيع.",
  "اختار اسمك واكتب الرقم السري 123456 (أو «دخول سريع»). كل شخص بيشوف الشاشات اللي مسموح له بيها بس.": "اختر اسمك وأدخل الرقم السري 123456 (أو «دخول سريع»). يرى كل شخص الشاشات المسموح له بها فقط.",
  "اضغط «جهازين» عشان تشوف شاشتين مع بعض — مثلًا الويتر بيبعت والمطبخ بيستلم. كليك يمين على أي جهاز بيفتحه في الشاشة التانية.": "اضغط «جهازان» لعرض شاشتين معًا — مثل الويتر يرسل والمطبخ يستلم. النقر بالزر الأيمن على أي جهاز يفتحه في الشاشة الثانية.",
  "السيستم ليه ساعة لوحده تقدر تقدّمها: مثلًا بعد نص الليل عشان تشوف إن البيع لسه على نفس اليوم التجاري، أو 12 ساعة عشان تنبيهات الإيصال الإلكتروني.": "للنظام ساعة مستقلة يمكنك تقديمها: مثلًا بعد منتصف الليل لترى أن البيع ما زال على اليوم التجاري نفسه، أو 12 ساعة لتنبيهات الإيصال الإلكتروني.",
  "وقّع الطابعة أو شاشة المطبخ أو منظومة الضرايب أو البرامج المربوطة، اقطع النت عن جهاز، أو ضيّع رد الشبكة — وشوف إن البيع بيكمل ومفيش حاجة بتتكرر.": "عطّل الطابعة أو شاشة المطبخ أو منظومة الضرائب أو البرامج المرتبطة، أو اقطع الاتصال عن جهاز، أو أسقط رد الشبكة — وتحقق من استمرار البيع دون تكرار.",
  "غيّر أي إعداد (مثلًا الخدمة 12%، أو الويتر يفتح شيك من غير درج) وشوف الأجهزة بتتصرف إزاي. التغيير بيطبق على اللي جاي بس.": "غيّر أي إعداد (مثل الخدمة 12%، أو فتح الويتر شيكًا بلا درج) وراقب سلوك الأجهزة. يُطبَّق التغيير على ما يأتي فقط.",
  "قصص جاهزة من يوم المطعم: كل خطوة بتقولك مين يعمل إيه وعلى أنهي جهاز والمفروض تشوف إيه. تعملها بإيدك أو السيستم يعملها قدامك.": "قصص جاهزة من يوم المطعم: تبيّن كل خطوة من يفعل ماذا وعلى أي جهاز وما الذي يجب أن تراه. نفّذها يدويًا أو دع النظام ينفذها أمامك.",
  "تجارب جاهزة لحاجات المفروض السيستم يرفضها: ضغطتين ورا بعض، جهازين في نفس اللحظة، مدير بيوافق لنفسه…": "تجارب جاهزة لما يجب أن يرفضه النظام: ضغطتان متتاليتان، جهازان في اللحظة نفسها، مدير يوافق لنفسه…",
  "شغّل «ملاحظة» من الشريط اللي فوق واضغط على أي حاجة في الشاشة واكتب رأيك (غلط، ناقص، مش واضح). بعدين نزّل الملاحظات كملف وابعتهولنا.": "شغّل «ملاحظة» من الشريط العلوي واضغط على أي عنصر في الشاشة واكتب رأيك (خطأ، نقص، غير واضح). ثم نزّل الملاحظات كملف وأرسله إلينا.",
  "رجّع بيانات التجربة زي الأول، أو ابدأ بمطعم فاضي، أو احفظ نسخة وارجعلها بعدين.": "أعد بيانات التجربة كما كانت، أو ابدأ بمطعم فارغ، أو احفظ نسخة وعُد إليها لاحقًا.",
