  "الويترية عندكم بيفتحوا ويعدّلوا شيكات الترابيزات من موبايلاتهم أو تابلتاتهم من غير درج فلوس؟ (الكاونتر والتيك أواي فاضلين بدرج)": "هل يفتح الويترز لديكم شيكات الترابيزات ويعدّلونها من هواتفهم أو أجهزتهم اللوحية بلا درج نقدية؟ (الكاونتر والتيك أواي يبقيان بدرج)",
  "الويتر يفتح شيك من غير درج": "فتح الويتر شيكًا بلا درج نقدية",
  "اتضاف في آخر نسخة من التصميم": "أُضيف في آخر نسخة من التصميم",
  "بيحدد هل الويتر يقدر يفتح ويعدّل شيكات الترابيزات من التابلت بتاعه من غير ما تكون فيه وردية درج مفتوحة. التيك أواي دايمًا محتاج درج.": "يحدد هل يستطيع الويتر فتح شيكات الترابيزات وتعديلها من تابلته دون وردية درج مفتوحة. التيك أواي يحتاج درجًا دائمًا.",
  "زرار «ابعت للمطبخ» في شاشة الشيك بيظهر أو يختفي.": "يظهر زر «إرسال للمطبخ» في شاشة الشيك أو يختفي.",
  "إمتى الطلب يروح المطبخ": "متى يُرسل الطلب للمطبخ",
  "الطلب يروح المطبخ على دفعات بزرار «ابعت للمطبخ» (مقبلات وبعدين رئيسي)، ولا مرة واحدة أول ما الشيك يتأكد.": "يُرسل الطلب للمطبخ على دفعات بزر «إرسال للمطبخ» (مقبلات ثم رئيسي)، أو دفعة واحدة فور تأكيد الشيك.",
  "زرار «شيك جديد» التاني على نفس الترابيزة.": "زر «شيك جديد» الثاني على الترابيزة نفسها.",
