  "المطعم داخل في إلزام الإيصال الإلكتروني للأفراد؟ وكود النشاط إيه؟ وإيصال المطاعم مناسب له؟": "هل يخضع المطعم لإلزام الإيصال الإلكتروني للأفراد؟ وما رمز النشاط؟ وهل يناسبه إيصال المطاعم؟",
  "مين ماسك شهادة التوقيع (فلاشة التوقيع ولا جهاز تشفير) وبيانات دخول المنظومة؟ — السر عمره ما بيتخزن في النظام.": "من يحتفظ بشهادة التوقيع (مفتاح التوقيع أو جهاز التشفير) وبيانات دخول المنظومة؟ — لا يُخزَّن السر في النظام أبدًا.",
  "أكواد الأصناف: باركود عالمي ولا نسجّل أكواد مصرية للمنيو؟ ومين اللي يسجلها؟": "رموز الأصناف: باركود عالمي أم نسجّل رموزًا مصرية للقائمة؟ ومن يسجلها؟",
  "الخدمة: تتكتب على الإيصال كسطر لوحدها؟ وبأنهي نوع ضريبة؟ — لحد الإجابة بتفضل برة الإيصال.": "الخدمة: هل تُكتب في الإيصال سطرًا مستقلًا؟ وبأي نوع ضريبة؟ — تبقى خارج الإيصال حتى الإجابة.",
  "الكارت المسجل هيتستخدم في التجربة؟ وكود وسيلة الدفع بتاعه إيه؟": "هل ستُستخدم البطاقة المسجلة في التجربة؟ وما رمز وسيلة الدفع الخاص بها؟",
  "شيك مدفوع كاش وكارت مع بعض والإيصال فيه وسيلة دفع واحدة — الافتراضي: الوسيلة الأكبر، والكاش لو اتساووا.": "شيك مدفوع نقدًا وبطاقة معًا والإيصال يقبل وسيلة دفع واحدة — الافتراضي: الوسيلة الأكبر، والنقد عند التساوي.",
