  "أي كسر بيتشال.": "يُحذف أي كسر.",
  "نسبة الخدمة على كل نوع طلب، وهل عليها ضريبة. بتظهر سطر لوحدها في الشيك ومش بتتحسب من المبيعات.": "نسبة الخدمة لكل نوع طلب، وهل عليها ضريبة. تظهر سطرًا مستقلًا في الشيك ولا تُحتسب من المبيعات.",
  "بتحدد إزاي السيستم يحسب الخدمة والضريبة لما الشيك يتأكد، وعلى أنهي نوع طلبات. لو مش متحددة، السيستم بيرفض التأكيد بدل ما يحسب غلط.": "يحدد كيف يحسب النظام الخدمة والضريبة عند تأكيد الشيك، وعلى أي أنواع طلبات. إن لم يُحدَّد يرفض النظام التأكيد بدل الحساب الخاطئ.",
