  "السعر المكتوب في المنيو هو اللي الزبون بيدفعه، والضريبة جواه.": "السعر المكتوب في القائمة هو ما يدفعه العميل، والضريبة داخله.",
  "حد الخصم اللي بيظهر للموظف": "حد الخصم الظاهر للموظف",
  "رقم بيظهر للموظف بس للتوضيح. اللي بيقرر فعلًا إمتى الخصم محتاج موافقة هي قاعدة «خصم على الشيك» في قسم الموافقات.": "رقم يظهر للموظف للتوضيح فقط. ما يقرر فعلًا متى يحتاج الخصم موافقة هو قاعدة «خصم على الشيك» في قسم الموافقات.",
  "ينفع خصم المدير يتجمع مع عرض على نفس الشيك؟ والعروض الأوتوماتيك (زي الهابي أور) تتطبق لوحدها؟": "هل يُجمع خصم المدير مع عرض على الشيك نفسه؟ وهل تُطبَّق العروض التلقائية (مثل هابي أور) وحدها؟",
