  "ينفع المدير يحدد سعر جديد يبدأ من بكرة مثلًا، ولا تغيير السعر بيحصل فورًا بس.": "هل يمكن للمدير تحديد سعر جديد يبدأ من الغد مثلًا، أم يتم تغيير السعر فورًا فقط.",
  "التغيير فوري بس": "التغيير فوري فقط",
  "السعر الجديد بيبدأ من دلوقتي.": "يبدأ السعر الجديد من الآن.",
  "أي صنف جديد بياخد الضريبة دي أوتوماتيك، إلا لو حد غيّرها.": "يأخذ أي صنف جديد هذه الضريبة تلقائيًا، ما لم يغيّرها أحد.",
  "الأصناف الجديدة وأكوادها ووقف الأصناف.": "الأصناف الجديدة ورموزها وإيقاف الأصناف.",
