  "لازم يتفعّل في كل فرع لوحده": "يجب تفعيله في كل فرع منفردًا",
  "الصنف مش هيظهر في أي فرع لحد ما حد يفعّله.": "لن يظهر الصنف في أي فرع حتى يفعّله أحد.",
  "لما صنف يخلص أو يتوقف، الموظف لازم يكتب السبب ولا اختياري.": "عند نفاد صنف أو إيقافه، هل كتابة السبب إلزامية على الموظف أم اختيارية.",
  "المدير يكتب كود كل صنف بنفسه، ولا السيستم يعمله أوتوماتيك لو اتساب فاضي.": "هل يكتب المدير رمز كل صنف بنفسه، أم ينشئه النظام تلقائيًا إن تُرك فارغًا.",
  "المدير يكتبه بنفسه": "يكتبه المدير بنفسه",
  "مفيش كود أوتوماتيك.": "لا رمز تلقائي.",
  "لو حد عمل صنف بنفس اسم صنف موجود: السيستم يمنعه، ينبّه بس، ولا يسيبه.": "إن أنشأ أحد صنفًا باسم صنف موجود: يمنعه النظام، أم ينبّه فقط، أم يتركه.",
  "تنبيه بس، ويتحفظ عادي": "تنبيه فقط، ويُحفظ عاديًا",
