  "الزبون يقدر يدفع بإيه: كاش، كارت، محفظة. الكارت والمحفظة بيتسجلوا برقم العملية بس (مفيش ربط بمكنة حقيقية).": "بماذا يدفع العميل: نقدي، بطاقة، محفظة. تُسجَّل البطاقة والمحفظة برقم العملية فقط (لا ربط بجهاز فعلي).",
  "لو مقفول: الدفع الجزئي بيترفض في شاشة التحصيل.": "عند التعطيل: يُرفض الدفع الجزئي في شاشة التحصيل.",
  "الزبون يقدر يقسم الشيك بين كاش وكارت مثلًا، ولا يدفع بطريقة واحدة بس.": "هل يقسّم العميل الشيك بين النقد والبطاقة مثلًا، أم يدفع بطريقة واحدة فقط.",
  "أي كاشير فاتح وردية في الفرع يقدر يحصّل شيك الترابيزة (والشيك بيفضل محسوب على الويتر)، ولا الوردية اللي فتحت الشيك بس.": "هل يحصّل أي كاشير فاتح وردية في الفرع شيك الترابيزة (ويبقى محسوبًا على الويتر)، أم الوردية التي فتحت الشيك فقط.",
  "الوردية اللي فتحت الشيك بس": "الوردية التي فتحت الشيك فقط",
  "الشيك لازم يتحصّل على نفس الدرج اللي اتفتح عليه.": "يجب تحصيل الشيك على الدرج نفسه الذي فُتح عليه.",
  "المرتجع يرجع إزاي": "طريقة إرجاع المرتجع",
  "فلوس المرتجع لازم ترجع بنفس طريقة الدفع، ولا ينفع ترجع كاش، ولا بأي طريقة.": "هل يُرد مبلغ المرتجع بطريقة الدفع نفسها، أم يمكن رده نقدًا، أم بأي طريقة.",
