  "وقت قفل الوردية، الكاشير يعد الفلوس من غير ما يشوف المبلغ اللي المفروض يكون في الدرج.": "عند إغلاق الوردية يعد الكاشير النقد دون رؤية المبلغ المتوقع في الدرج.",
