  "إنستاباي وفودافون كاش وغيرهم كطرق دفع برقم العملية، وكل واحدة تظهر سطر لوحدها في تقرير قفلة الوردية.": "إنستاباي وفودافون كاش وغيرها كطرق دفع برقم العملية، وتظهر كل منها سطرًا مستقلًا في تقرير إغلاق الوردية.",
