  "جولات صريحة (زرار \"ابعت للمطبخ\") ولا الإرسال وقت التأكيد بس. نوع الإرسال بيتثبت على الشيك أول ما يتبعت.": "جولات صريحة (زر \"إرسال للمطبخ\") أم الإرسال عند التأكيد فقط. يُثبَّت نوع الإرسال على الشيك فور إرساله.",
