  "اختياري — اكتبه لو موجود. نفس الرقم مايتسجلش مرتين في نفس اليوم.": "اختياري — أدخله إن وُجد. لا يُسجَّل الرقم نفسه مرتين في اليوم نفسه.",
  "اتطبع من النظام — القالب بيتظبط من «قوالب الإيصال والتقارير».": "طُبع من النظام — يُضبط القالب من «قوالب الإيصال والتقارير».",
  "رجّع فلوس لزبون على شيك اتدفع. الكاشير بيصرف من درجه، والمدير بيوافق على نفس الجهاز.": "إرجاع مبلغ لعميل على شيك مدفوع. يصرف الكاشير من درجه، ويوافق المدير على الجهاز نفسه.",
  "المرتجع الكاش بيطلع من درج الكاشير اللي بيعمله: اطلبه واصرفه من جهاز الكاشير، والمدير يوافق هناك بالرقم السري أو الكارت أو البصمة — أو يوافق على الطلب من جهازه.": "يخرج المرتجع النقدي من درج الكاشير المنفذ: اطلبه واصرفه من جهاز الكاشير، ويوافق المدير هناك بالرقم السري أو البطاقة أو البصمة — أو يوافق على الطلب من جهازه.",
  "اكتب رقم الشيك اللي على الإيصال (مثلًا 0388 من امبارح).": "أدخل رقم الشيك المطبوع على الإيصال (مثل 0388 من الأمس).",
  "دوّر برقم الشيك الأول، وبعدها اختار الأصناف — المبلغ بيتحسب لوحده.": "ابحث برقم الشيك أولًا، ثم اختر الأصناف — يُحسب المبلغ تلقائيًا.",
  "الشيك ده اتدفع يوم {d} واليوم ده اتقفل. المرتجع هيتسجل على يوم {b} ومربوط بالشيك الأصلي — أرقام يوم {d} مش هتتغير. الصرف محتاج الصلاحية التالتة (المحاسب أو صاحب المطعم).": "دُفع هذا الشيك يوم {d} وأُغلق ذلك اليوم. سيُسجَّل المرتجع على يوم {b} مرتبطًا بالشيك الأصلي — لن تتغير أرقام يوم {d}. الصرف يحتاج الصلاحية الثالثة (المحاسب أو صاحب المطعم).",
  "مرتجع في نفس اليوم": "مرتجع في اليوم نفسه",
  "الفلوس هتطلع من درج الكاشير اللي على الجهاز ده، والمدير يوافق هنا على نفس الجهاز.": "يخرج المبلغ من درج الكاشير على هذا الجهاز، ويوافق المدير هنا على الجهاز نفسه.",
  "طلب المرتجع اتسجل": "تم تسجيل طلب المرتجع",
  "المرتجع اتصرف من الدرج": "صُرف المرتجع من الدرج",
  "الصنف هيروح فين": "مصير الصنف",
  "اصرف دلوقتي من الدرج اللي على الجهاز ده (المدير يوافق هنا)": "الصرف الآن من الدرج على هذا الجهاز (يوافق المدير هنا)",
  "الصرف هيكون من جهاز الكاشير": "يتم الصرف من جهاز الكاشير",
  "اطلب واصرف": "طلب وصرف",
  "وجبة الموظف مش بيع ومفيش فلوس بترجع — بتتلغي أو تترجع بموافقة حسب المرحلة، والمخزن بيتظبط.": "وجبة الموظف ليست بيعًا ولا يُرد عنها مبلغ — تُلغى أو تُرجع بموافقة حسب المرحلة، ويُضبط المخزن.",
  "الوجبة دي اتلغت قبل كده.": "أُلغيت هذه الوجبة سابقًا.",
  "بعد قفل اليوم": "بعد إغلاق اليوم",
  "مين عمل ومين وافق": "المنفذ والموافق",
  "اتسجل يوم": "سُجّل يوم",
  "اصرف (موافقة مدير)": "صرف (موافقة مدير)",
  "الموافقة لازم تكون من مدير غير اللي طلب، والصرف الكاش بيطلع من الدرج المفتوح على الجهاز اللي بيصرف — عشان يتعرف الفلوس طلعت من درج مين.": "يجب أن تكون الموافقة من مدير غير الطالب، ويُصرف النقد من الدرج المفتوح على الجهاز الصارف — ليُعرف من أي درج خرج المبلغ.",
  "كل موافقة مدير بتتستخدم مرة واحدة على حركة واحدة بعينها. والسجل بيقول مين عمل إيه، ومين سمح بيها، إمتى، ومن أنهي جهاز.": "كل موافقة مدير تُستخدم مرة واحدة على حركة محددة. ويبيّن السجل من فعل ماذا، ومن سمح به، ومتى، ومن أي جهاز.",
  "وافق في مكان الموظف": "وافق بدلًا من الموظف",
  "الحركة مش من صلاحية اللي طلب — المدير وافق في مكانه": "الحركة خارج صلاحية الطالب — وافق المدير بدلًا منه",
  "مين عمل": "المنفذ",
  "مين سمح": "المُصرِّح",
  "في مكان الموظف": "بدلًا من الموظف",
  "اختار صورة (PNG أو JPG أو SVG).": "اختر صورة (PNG أو JPG أو SVG).",
  "اللوجو كبير — أقصى حاجة حوالي 200 كيلوبايت. صغّر الصورة وجرب تاني.": "الشعار كبير — الحد الأقصى نحو 200 كيلوبايت. صغّر الصورة وأعد المحاولة.",
  "الصورة دي ما اتقريتش. جرّب ملف تاني.": "تعذرت قراءة هذه الصورة. جرّب ملفًا آخر.",
  "القالب اتحفظ — الإيصالات والتقارير الجاية هتطلع بيه": "تم حفظ القالب — ستصدر به الإيصالات والتقارير القادمة",
  "اللوجو وسطور الإيصال من فوق ومن تحت، ومقاس الورق، واللغة التانية، ورقم النداء. السيستم هو اللي بيطبع اللوجو — مش محتاج تبرمجه على الطابعة.": "الشعار وسطور الإيصال العلوية والسفلية، ومقاس الورق، واللغة الثانية، ورقم النداء. يطبع النظام الشعار — لا حاجة لبرمجته على الطابعة.",
  "احفظ القالب": "حفظ القالب",
  "لوجو المطعم": "شعار المطعم",
  "PNG أو JPG أو SVG — بيتصغّر لوحده، وأقصى حجم حوالي 200 كيلوبايت.": "PNG أو JPG أو SVG — يُصغَّر تلقائيًا، والحد الأقصى نحو 200 كيلوبايت.",
  "مفيش لوجو": "لا يوجد شعار",
  "غيّر اللوجو": "تغيير الشعار",
  "ارفع لوجو": "رفع شعار",
