  "مفيش اختيار = كل المحطات.": "بلا اختيار = كل المحطات.",
  "شاشة تسليم (إكسبو)": "شاشة تسليم (Expo)",
  "عليها «جاهز للتسليم» والتسليم للويتر. شاشات المحطات التانية «جاهز» عندها بيبعت الطلب هنا.": "عليها «جاهز للتسليم» والتسليم للويتر. «جاهز» في شاشات المحطات الأخرى يرسل الطلب إليها.",
  "زرار «ابدأ»": "زر «بدء»",
