  "من غير ما تغيّر الدور كله: زوّد صلاحية للشخص ده، أو شيل منه صلاحية، ولو عايز لمدة محددة. بيتحفظ لوحده وبيتسجل في السجل.": "دون تغيير الدور كله: أضف صلاحية لهذا الشخص، أو اسحب منه صلاحية، ولمدة محددة إن أردت. يُحفظ منفردًا ويُسجَّل في السجل.",
