  "كل اللي يحتاجه الصنف عشان يتباع في مكان واحد: الاسم، السعر في كل قناة، الضريبة، بيتخزن إزاي، الحد الأدنى وأول استلام.": "كل ما يحتاجه الصنف ليُباع في مكان واحد: الاسم، والسعر في كل قناة، والضريبة، وطريقة التخزين، والحد الأدنى وأول استلام.",
