  "كل قناة بيع ليها نوع طلب (صالة، تيك أواي، دليفري) وقايمة أسعار. ضيف قناة زي «طلبات» بأسعارها من غير ما تغيّر أسعار الصالة.": "لكل قناة بيع نوع طلب (صالة، تيك أواي، دليفري) وقائمة أسعار. أضف قناة مثل «طلبات» بأسعارها دون تغيير أسعار الصالة.",
  "نوع الطلب بيحدد الشغل: يروح المطبخ إزاي، عليه خدمة ولا لأ، وله توصيل ولا لأ. القناة بتحدد السعر بس. الطلب اللي جاي من «طلبات» بيتعامل كدليفري، لكن بأسعار طلبات.": "يحدد نوع الطلب طريقة العمل: كيف يصل للمطبخ، وهل عليه خدمة، وهل له توصيل. القناة تحدد السعر فقط. الطلب الوارد من «طلبات» يُعامل كدليفري، لكن بأسعار طلبات.",
