  "الكمية في الفاتورة = اللي اتستلم بالظبط ومينفعش تتغير. لو المورد كاتب سعر مختلف، اكتبه — الفرق بيظهر كـ«فرق سعر» والرصيد مش بيتغير.": "الكمية في الفاتورة = المستلم تمامًا ولا تتغير. إن كتب المورد سعرًا مختلفًا فأدخله — يظهر الفرق كـ«فرق سعر» ولا يتغير الرصيد.",
