  "دي معاينة بس — وقت السيرفر ما اتغيرش، والكاشير لسه شايف منيو دلوقتي.": "هذه معاينة فقط — لم يتغير وقت الخادم، وما زال الكاشير يرى قائمة الآن.",
  "اختار ساعة فوق عشان تعاين الفطار والعشا من غير ما الوقت يتغير.": "اختر ساعة أعلاه لمعاينة الإفطار والعشاء دون تغيير الوقت.",
  "الشاشة دي لفريق NerdPOS بس": "هذه الشاشة لفريق NerdPOS فقط",
  "الأجزاء المرخصة من السيستم بيفتحها ويقفلها فريق NerdPOS حسب الترخيص — مش صاحب المطعم ولا الـIT بتاعه. كلّم الدعم لو محتاج جزء جديد.": "يفعّل فريق NerdPOS الأجزاء المرخصة من النظام ويعطلها حسب الترخيص — لا صاحب المطعم ولا فريق IT لديه. تواصل مع الدعم إن احتجت جزءًا جديدًا.",
  "شاشة فريق NerdPOS — مش ظاهرة للمطعم": "شاشة فريق NerdPOS — غير ظاهرة للمطعم",
  "الأجزاء دي مرتبطة بترخيص المطعم. صاحب المطعم والمدير والـIT بتوعهم ما بيشوفوش الشاشة دي ومش يقدروا يغيّروها؛ أي تغيير بيتسجل باسمك في سجل النشاط.": "ترتبط هذه الأجزاء بترخيص المطعم. لا يرى صاحب المطعم والمدير وفريق IT لديهم هذه الشاشة ولا يستطيعون تغييرها؛ يُسجَّل أي تغيير باسمك في سجل النشاط.",
