  "لو المطبخ ما بدأش = ما اتعملش، لو بدأ = هالك محفوظ": "إن لم يبدأ المطبخ = لم يُحضَّر، وإن بدأ = هالك محفوظ",
  "الصنف هيروح فين؟": "ما مصير الصنف؟",
  "الصنف اتبعت للمطبخ فمينفعش يتشال من غير أثر. الإلغاء محتاج موافقة مدير (ينفع على نفس الجهاز)، وبيظهر مشطوب على شاشة المطبخ ومتسجل باسمك واسم المدير.": "أُرسل الصنف للمطبخ فلا يُزال دون أثر. الإلغاء يحتاج موافقة مدير (ممكنة على الجهاز نفسه)، ويظهر مشطوبًا على شاشة المطبخ ومسجلًا باسمك واسم المدير.",
  "شيل صنف": "إزالة صنف",
  "الصنف ده ظهر للزبون في الشيك المبدئي. الشيل محتاج سبب وموافقة مدير، ومتسجل باسمك واسم المدير — مش هيختفي من السجل.": "ظهر هذا الصنف للعميل في الشيك المبدئي. الإزالة تحتاج سببًا وموافقة مدير، وتُسجَّل باسمك واسم المدير — ولن تختفي من السجل.",
  "حتى قبل الإرسال، الشيل محتاج موافقة مدير (حسب إعدادات المطعم)، ومتسجل في سجل الشيك باسمك واسم المدير.": "حتى قبل الإرسال، تحتاج الإزالة موافقة مدير (حسب إعدادات المطعم)، وتُسجَّل في سجل الشيك باسمك واسم المدير.",
  "الصنف اتشال واتسجل": "أُزيل الصنف وسُجّل",
  "الكمية اتقللت واتسجلت": "قُلّلت الكمية وسُجّلت",
  "ده محتاج موافقة مدير دايمًا (ينفع على نفس الجهاز). الشيك اللي عليه فلوس اتدفعت مينفعش يتلغي — اعمل له مرتجع.": "يحتاج هذا موافقة مدير دائمًا (ممكنة على الجهاز نفسه). لا يُلغى شيك عليه مدفوعات — أنشئ له مرتجعًا.",
  "اسأل بالعامية أو بالإنجليزي. الإجابة من نفس المقاييس المعتمدة اللي في التقارير، ومعاها التعريف والفترة ولحد إمتى والشيكات اللي ورا الرقم. لو السؤال مش واضح هسألك سؤال واحد، ولو المصدر مش موجود هقول «مش متاح» مش صفر.": "اسأل بالعربية (ولو بالعامية) أو بالإنجليزية. تأتي الإجابة من المقاييس المعتمدة نفسها في التقارير، مع التعريف والفترة وحتى متى والشيكات التي خلف الرقم. إن لم يكن السؤال واضحًا أسألك سؤالًا واحدًا، وإن لم يوجد المصدر أقول «غير متاح» لا صفر.",
  "مثلًا: صافي المبيعات امبارح، مين أكتر ويتر بيلغي، الخامات الناقصة…": "مثال: صافي مبيعات الأمس، أكثر ويتر يلغي، الخامات الناقصة…",
  "اسأل": "سؤال",
  "بنك الأسئلة (198 سؤال من البحث)": "بنك الأسئلة (198 سؤالًا من البحث)",
  "الأسئلة اللي المساعد اتجرب عليها — دوس على أي سؤال يتسأل. النتيجة لكل عائلة في تقرير التقييم.": "الأسئلة التي جُرّب عليها المساعد — اضغط على أي سؤال لطرحه. النتيجة لكل عائلة في تقرير التقييم.",
  "مساعد بقواعد ثابتة (من غير ذكاء اصطناعي) — بيترجم سؤالك لاستعلام على قاموس المقاييس ويجاوب بالأرقام المعتمدة ومصدرها.": "مساعد بقواعد ثابتة (بلا ذكاء اصطناعي) — يحوّل سؤالك إلى استعلام على قاموس المقاييس ويجيب بالأرقام المعتمدة ومصدرها.",
  "كل رقم في التقارير بيطلع من نفس الطبقات: الأحداث ← قاموس المقاييس ← التقارير المعتمدة ← التحليل ← الإثبات ← المساعد. هنا بتشوف المحرك نفسه، مش صفحات.": "كل رقم في التقارير يصدر من الطبقات نفسها: الأحداث ← قاموس المقاييس ← التقارير المعتمدة ← التحليل ← الإثبات ← المساعد. هنا ترى المحرك نفسه، لا صفحات.",
  "جرّب استعلام": "تجربة استعلام",
