  "{a} متاح · {n} مش متاح (بالسبب)": "{a} متاح · {n} غير متاح (مع السبب)",
  "{p} من القايمة التجريبية + {x} إضافي (التقريب، الإلغاءات بالمراحل، طابور المراجعة، مصفوفة المنيو) · {g} تقارير قديمة شغالة زي ما هي": "{p} من القائمة التجريبية + {x} إضافي (التقريب، الإلغاءات بالمراحل، طابور المراجعة، مصفوفة القائمة) · {g} تقارير قديمة تعمل كما هي",
  "مقارنة فترات، اتجاه، «ليه اتغير» (حجم × سعر × تشكيلة + غير مفسَّر)، مصفوفة المنيو": "مقارنة فترات، واتجاه، و«لماذا تغيّر» (حجم × سعر × تشكيلة + غير مفسَّر)، ومصفوفة القائمة",
  "أي رقم ← الشيكات والسطور والدفعات اللي وراه، ومجموعهم = الرقم": "أي رقم ← الشيكات والسطور والدفعات التي خلفه، ومجموعها = الرقم",
  "مساعد بقواعد ثابتة، متجرّب على {n} سؤال": "مساعد بقواعد ثابتة، مُجرَّب على {n} سؤال",
  "L0 — الأحداث اللي المحرك بيقرا منها": "L0 — الأحداث التي يقرأ منها المحرك",
  "كل حقيقة ليها يوم تجاري، ووقت تسجيل (لـ asOf)، والأبعاد اللي بتحملها، ومؤشر للسجل الأصلي.": "لكل حقيقة يوم تجاري، ووقت تسجيل (لـ asOf)، والأبعاد التي تحملها، ومؤشر إلى السجل الأصلي.",
  "أول يوم فيه أحداث تفصيلية: {d}. الأيام قبله عندها إجماليات يومية مستوردة بس.": "أول يوم به أحداث تفصيلية: {d}. الأيام السابقة له بها إجماليات يومية مستوردة فقط.",
  "كل تقرير = تركيبة من مقاييس وأبعاد مسجلة + غرض + جمهور + مطابقة + قايمة مراجعة. مفيش حسابات فلوس جوه الشاشة.": "كل تقرير = تركيبة من مقاييس وأبعاد مسجلة + غرض + جمهور + مطابقة + قائمة مراجعة. لا حسابات مالية داخل الشاشة.",
  "مش لصلاحيتك": "خارج صلاحيتك",
