  "دوّر على مقياس": "ابحث عن مقياس",
  "دقايق": "دقائق",
  "اختار مقاييس وبُعد وفترة — المحرك هيجاوب، أو يرفض التقاطع بالسبب، أو يقول «مش متاح». كل رقم بيفتح الشيكات اللي وراه.": "اختر مقاييس وبُعدًا وفترة — يجيب المحرك، أو يرفض التقاطع مع السبب، أو يقول «غير متاح». كل رقم يفتح الشيكات التي خلفه.",
