  "اقرا كل بند وإزاي المحرك بيعمله دلوقتي، وقول: صح / غلط / عندي سؤال. التوقيع والملاحظات بتتحفظ على الجهاز ده وبتنزل مع ملف الملاحظات.": "اقرأ كل بند وكيف ينفذه المحرك حاليًا، وحدد: صحيح / خطأ / لدي سؤال. يُحفظ التوقيع والملاحظات على هذا الجهاز وتُنزَّل مع ملف الملاحظات.",
