  "في البروتوتايب الإرسال بيتسجل بس (مفيش إيميل بيتبعت فعلاً) — والملفات بتتعمل وتقدر تفتحها من هنا.": "في النموذج الأولي يُسجَّل الإرسال فقط (لا يُرسل بريد فعلي) — وتُنشأ الملفات ويمكنك فتحها من هنا.",
