  "كل إجمالي وإجمالي فرعي بيتحسب من جديد من السجلات — النسب من مجاميعها، والعدد من غير تكرار، والمخزون لقطة في لحظة واحدة. «مش متاح» معناه إن البيانات مش موجودة، مش صفر.": "يُحسب كل إجمالي وإجمالي فرعي من جديد من السجلات — النسب من مجاميعها، والعدد بلا تكرار، والمخزون لقطة في لحظة واحدة. «غير متاح» يعني أن البيانات غير موجودة، لا صفر.",
